import{_ as a}from"./chunks/dispatch-week.BMCYSnKC.js";import{_ as t,o as r,c as s,a2 as i}from"./chunks/framework.CWgsre3x.js";const v=JSON.parse('{"title":"Dispatch schedule","description":"","frontmatter":{},"headers":[],"relativePath":"plus/dispatch-schedule.md","filePath":"plus/dispatch-schedule.md"}'),n={name:"plus/dispatch-schedule.md"};function o(c,e,l,d,h,p){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="dispatch-schedule" tabindex="-1">Dispatch schedule <a class="header-anchor" href="#dispatch-schedule" aria-label="Permalink to &quot;Dispatch schedule&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>TransferBook+ v0.7.9 source baseline. This is a local review draft, not confirmation of production availability. Use only an authorized environment and verify the installed version and permissions.</p></div><h2 id="illustrated-workspace" tabindex="-1">Illustrated workspace <a class="header-anchor" href="#illustrated-workspace" aria-label="Permalink to &quot;Illustrated workspace&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/dispatch-week.png"><img src="'+a+'" alt="Weekly dispatch view: use Day, Week or Month, the date selector and status filter to inspect scheduled work."></a></p><p><em>Select the screenshot to open it at its original size. Use your browser’s Back button to return.</em></p><p><em>Weekly dispatch view: use Day, Week or Month, the date selector and status filter to inspect scheduled work.</em></p><p>Staging capture, TransferBook+ v0.7.11; English UI. Illustrative test data. This image does not establish production availability. Identifiers masked.</p><h2 id="purpose-and-access" tabindex="-1">Purpose and access <a class="header-anchor" href="#purpose-and-access" aria-label="Permalink to &quot;Purpose and access&quot;">​</a></h2><p>The dispatch calendar provides day, week and month views for an authorized operator to review workload and scheduling.</p><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li>Open <strong>Dispatch Timeline &amp; Daily Schedule</strong> or the calendar view.</li><li>Choose day, week or month. Select the relevant date/period and operating hub.</li><li>Filter by <strong>All statuses</strong>, <strong>Quote required</strong>, <strong>Tour acceptance pending</strong>, <strong>Dispatch review</strong>, <strong>Assigned / In transit</strong>, or <strong>Completed / Cancelled</strong>.</li><li>Review scheduled pickups in chronological context. Check the booking detail before taking an assignment action.</li><li>Verify the driver, vehicle, capacity, region and overlapping work before dispatching through the authorized controls.</li></ol><h2 id="expected-result" tabindex="-1">Expected result <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Expected result&quot;">​</a></h2><p>The selected period and filters display matching bookings. Review and quote-pending items are not equivalent to dispatch-ready bookings.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If a trip is missing, check hub, period and status filter. If assignment is refused, resolve scheduling or capacity conflicts. See <a href="/plus/assignments.html">Driver and vehicle assignment</a>.</p><h2 id="changes-described-in-v0-7-14" tabindex="-1">Changes described in v0.7.14 <a class="header-anchor" href="#changes-described-in-v0-7-14" aria-label="Permalink to &quot;Changes described in v0.7.14&quot;">​</a></h2><p>The published release describes responsive layout corrections, improved date navigation and calendar presentation, internal dispatch notes and authorized overrides with mandatory audit justification. Review the current calendar and assignment details before acting. An override is not a general bypass: use it only when authorized, document the actual reason and verify the resulting assignment. Exact controls and permissions require release-specific acceptance. The illustration above remains a historical v0.7.11 capture.</p><p>See <a href="/release-notes/">Release Notes</a>.</p><h2 id="v0-7-26-dispatch-review" tabindex="-1">v0.7.26 dispatch review <a class="header-anchor" href="#v0-7-26-dispatch-review" aria-label="Permalink to &quot;v0.7.26 dispatch review&quot;">​</a></h2><p>Verify the full assignment interval, configured buffer, chauffeur duty/absence, vehicle maintenance and passenger/luggage capacity. Concurrent assignments can be rejected by resource locking; refresh and resolve the conflict rather than forcing an assignment. Return legs are independent. If an arrival advisory proposes a pickup change, review evidence and tariff date/night boundaries before approving; inspect the saved schedule afterwards. See <a href="/plus/arrival-intelligence.html">Arrival intelligence</a> and <a href="/plus/subcontractors.html">Subcontractors</a>.</p>',20)])])}const f=t(n,[["render",o]]);export{v as __pageData,f as default};
